import{_ as i,C as r,o as a,c as d,j as s,a as t,b as c,w as n,E as l,ao as p,an as h}from"./chunks/framework.DMeMo5mc.js";const k=JSON.parse('{"title":"Architecture tour","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/architecture.md","filePath":"concepts/architecture.md","lastUpdated":null}'),u={name:"concepts/architecture.md"};function m(g,e,f,b,y,v){const o=r("Mermaid");return a(),d("div",null,[e[1]||(e[1]=s("h1",{id:"Architecture-tour",tabindex:"-1"},[t("Architecture tour "),s("a",{class:"header-anchor",href:"#Architecture-tour","aria-label":'Permalink to "Architecture tour {#Architecture-tour}"'},"​")],-1)),e[2]||(e[2]=s("p",null,"This page explains the shape of AtmosTransport before the detailed pages introduce grids, state, operators, and binary fields. It is written for model users first; source-code pointers are collected at the end.",-1)),e[3]||(e[3]=s("h2",{id:"Two-programs,-one-contract",tabindex:"-1"},[t("Two programs, one contract "),s("a",{class:"header-anchor",href:"#Two-programs,-one-contract","aria-label":'Permalink to "Two programs, one contract {#Two-programs,-one-contract}"'},"​")],-1)),e[4]||(e[4]=s("p",null,"AtmosTransport deliberately separates expensive meteorology preparation from the repeated transport calculation:",-1)),(a(),c(p,null,{default:n(()=>[l(o,{id:"mermaid-12",class:"mermaid-diagram",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20offline%5BOffline%20preprocessing%5D%0A%20%20%20%20%20%20%20%20RAW%5BERA5%20GRIB%20or%20GEOS%20NetCDF%5D%0A%20%20%20%20%20%20%20%20READ%5BTyped%20meteorology%20reader%5D%0A%20%20%20%20%20%20%20%20TRANSFORM%5BVertical%20and%20horizontal%20transforms%5D%0A%20%20%20%20%20%20%20%20BALANCE%5BDry-air%20conversion%20and%20mass%20balance%5D%0A%20%20%20%20%20%20%20%20VERIFY%5BReplay%20and%20positivity%20gates%5D%0A%20%20%20%20%20%20%20%20RAW%20--%3E%20READ%20--%3E%20TRANSFORM%20--%3E%20BALANCE%20--%3E%20VERIFY%0A%20%20%20%20end%0A%0A%20%20%20%20VERIFY%20--%3E%20BINARY%5BVersion-4%20transport%20binary%5D%0A%0A%20%20%20%20subgraph%20runtime%5BRuntime%5D%0A%20%20%20%20%20%20%20%20CONFIG%5BRun%20TOML%5D%0A%20%20%20%20%20%20%20%20DRIVER%5BTransportBinaryDriver%5D%0A%20%20%20%20%20%20%20%20GRID%5BAtmosGrid%5D%0A%20%20%20%20%20%20%20%20STATE%5BTracer%20and%20air-mass%20state%5D%0A%20%20%20%20%20%20%20%20OPERATORS%5BAdvection%20%2B%20optional%20physics%5D%0A%20%20%20%20%20%20%20%20MODEL%5BTransportModel%5D%0A%20%20%20%20%20%20%20%20SIM%5BDrivenSimulation%5D%0A%20%20%20%20%20%20%20%20OUTPUT%5BNetCDF%20or%20ATMSNAP%5D%0A%20%20%20%20%20%20%20%20CONFIG%20--%3E%20OPERATORS%0A%20%20%20%20%20%20%20%20CONFIG%20--%3E%20STATE%0A%20%20%20%20%20%20%20%20BINARY%20--%3E%20DRIVER%0A%20%20%20%20%20%20%20%20DRIVER%20--%3E%20GRID%0A%20%20%20%20%20%20%20%20DRIVER%20--%3E%20STATE%0A%20%20%20%20%20%20%20%20GRID%20--%3E%20MODEL%0A%20%20%20%20%20%20%20%20STATE%20--%3E%20MODEL%0A%20%20%20%20%20%20%20%20OPERATORS%20--%3E%20MODEL%0A%20%20%20%20%20%20%20%20MODEL%20--%3E%20SIM%0A%20%20%20%20%20%20%20%20DRIVER%20--%3E%20SIM%0A%20%20%20%20%20%20%20%20SIM%20--%3E%20OUTPUT%0A%20%20%20%20end%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=h(`<p>The <strong>transport binary</strong> is the boundary between those programs. It is not a generic data dump: its header declares topology, vertical coordinate, time windows, mass basis, flux semantics, optional physics payloads, and the exact substep schedule. The current reader accepts version 4 only.</p><p>This split keeps runtime I/O predictable and makes preprocessing assumptions auditable. The cost is that a real-data run cannot start from raw wind files; they must first be turned into a verified binary.</p><h2 id="The-five-runtime-objects" tabindex="-1">The five runtime objects <a class="header-anchor" href="#The-five-runtime-objects" aria-label="Permalink to &quot;The five runtime objects {#The-five-runtime-objects}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Object</th><th style="text-align:right;">Plain-language role</th><th style="text-align:right;">Usually created by</th></tr></thead><tbody><tr><td style="text-align:right;"><code>TransportBinaryDriver</code></td><td style="text-align:right;">Memory-maps forcing and loads one meteorological window at a time.</td><td style="text-align:right;"><code>run_driven_simulation</code></td></tr><tr><td style="text-align:right;"><code>AtmosGrid</code></td><td style="text-align:right;">Combines horizontal topology, hybrid-pressure levels, architecture, and planet constants.</td><td style="text-align:right;">Reconstructed from the binary header</td></tr><tr><td style="text-align:right;"><code>CellState</code> or <code>CubedSphereState</code></td><td style="text-align:right;">Stores air mass and conservative <code>mixing ratio × carrier-air-mass</code> tracer fields.</td><td style="text-align:right;">Initial-condition builder</td></tr><tr><td style="text-align:right;"><code>TransportModel</code></td><td style="text-align:right;">Bundles state, grid, face fluxes, operators, and reusable workspaces.</td><td style="text-align:right;">Runtime physics recipe</td></tr><tr><td style="text-align:right;"><code>DrivenSimulation</code></td><td style="text-align:right;">Connects model and driver, refreshes forcing, and advances windows/substeps.</td><td style="text-align:right;">High-level runner</td></tr></tbody></table><p>For normal runs, you configure these objects indirectly through TOML and call:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/run_transport.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_run.toml</span></span></code></pre></div><p>For custom experiments, the same construction is available through <code>run_driven_simulation(cfg)</code> or the lower-level public API.</p><h2 id="Configuration-becomes-types" tabindex="-1">Configuration becomes types <a class="header-anchor" href="#Configuration-becomes-types" aria-label="Permalink to &quot;Configuration becomes types {#Configuration-becomes-types}&quot;">​</a></h2><p>A TOML file is intentionally untyped text:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">advection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scheme = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;slopes&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">diffusion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kind = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;none&quot;</span></span></code></pre></div><p>At the runtime boundary, AtmosTransport validates those strings and constructs typed specifications and operators such as <code>SlopesScheme()</code> and <code>NoDiffusion()</code>. Unsupported combinations fail before stepping—for example, requesting TM5 convection against a binary without the four TM5 convection fields.</p><p>Inside the model loop, Julia&#39;s multiple dispatch chooses methods from the concrete operator, grid, state, numeric type, and architecture. The result is one user-facing workflow without a chain of topology strings or backend conditionals in every kernel.</p><h2 id="Execution-backends" tabindex="-1">Execution backends <a class="header-anchor" href="#Execution-backends" aria-label="Permalink to &quot;Execution backends {#Execution-backends}&quot;">​</a></h2><p><code>[architecture] backend</code> accepts <code>&quot;cpu&quot;</code>, <code>&quot;cuda&quot;</code>, <code>&quot;rocm&quot;</code>, <code>&quot;metal&quot;</code>, or <code>&quot;auto&quot;</code>. GPU runtimes are optional package extensions. ROCm uses AMDGPU.jl and supports Float32 and Float64; Metal requires Float32. ROCm hardware validation on MI300X/MI355X is pending. See the <a href="./../development/rocm">ROCm runbook</a> for installation, opt-in smoke checks, and profiling. Auto detection tries Metal → CUDA → ROCm on macOS, and CUDA → ROCm on Linux and other hosts, stopping at the first functional runtime.</p><h2 id="Kernels-written-once,-fused-by-dispatch" tabindex="-1">Kernels written once, fused by dispatch <a class="header-anchor" href="#Kernels-written-once,-fused-by-dispatch" aria-label="Permalink to &quot;Kernels written once, fused by dispatch {#Kernels-written-once,-fused-by-dispatch}&quot;">​</a></h2><p>Work that runs independently at every index of a block can be written as a <em>point operation</em>: a small struct (<code>&lt;: AbstractPointOp</code> in <code>Architectures</code>) with an <code>index_space</code> and an <code>apply_point!</code> body for one index. The same body runs as one GPU kernel or as a loop on the CPU (an operation with much work per index, such as the cubed-sphere surface-flux column walk, declares <code>host_parallel</code> and runs as the kernel on the CPU backend&#39;s threads instead). Operations compose by type:</p><ul><li><p><code>Fused(ops...)</code> combines independent operations (disjoint writes, no cross reads; for example the 24 panel edges of a cubed-sphere halo exchange). How it runs depends on the backend (below);</p></li><li><p><code>Sequence(ops...)</code> launches dependent operations in order with one synchronization (the corner fill, which reads the filled edges).</p></li></ul><p>How a backend launches a <code>Fused</code> set is its <code>fusion_policy</code>: one kernel with a trailing slot index by default (fastest on CUDA, where these kernels are bound by launch latency), or one launch per operation on that operation&#39;s <code>bound_context</code> (Metal, where that is faster; the halo operations bind their panel arrays there).</p><p>Fusing changes only how work is launched; every index performs the same arithmetic, so results do not change. The cubed-sphere halo exchange is built this way. With the default policy (CUDA) that is one launch for all 24 panel edges, a second for the corners when a sweep direction asks for them, and one synchronization; on Metal, 24 edge and 6 corner launches with bound arrays and one synchronization. Before, a 3-D field took 24 edge launches and 6 corner launches (one per panel, filling its four corners), and a packed tracer field 6 edge launches (one per panel) and 6 corner launches, with a synchronization after the edges and after the corners. Measured on an NVIDIA L40S for a C90 field with 72 levels in Float32 (edges, corners and synchronization), one exchange takes about 25 µs instead of 120 µs. Inside the packed cubed-sphere palindrome (<code>strang_split_cs_mt!</code>) the exchanges are only queued (<code>sync = false</code>): the palindrome synchronizes once, at its end.</p><p>Every device launch of a point operation runs over the flat linear index of its index space and recovers the index tuple with 32-bit integer divisions (64-bit from 2³¹ indices on). A launch over the index tuple itself puts each workgroup along the first dimension only, so short first dimensions leave most lanes idle: 96 of 256 for a C90 field, 3 of 256 for a halo corner fill of width 3. On an M5 Pro the flat launch cut the GPU time of a C90 window unpack from 4.7 to 1.0 ms.</p><p>Sets of same-sized device-to-device copies go through <code>copy_arrays!</code>: on every device backend (CUDA, ROCm, Metal), one queued <code>LinearCopy</code> launch over the longest array instead of one <code>copyto!</code> per array, when all arrays live on one backend (the host, and batches that mix backends, keep plain <code>copyto!</code>s). The cubed-sphere forcing refresh copies its 18 flux panels this way at a window&#39;s first step (at every step when the fluxes are interpolated within the window). On CUDA and ROCm this saves launches; on Metal it also removes the queue synchronization Metal.jl performs around every <code>copyto!</code>, which cost about 2.5 ms per step on an M5 Pro.</p><h2 id="One-transport-window" tabindex="-1">One transport window <a class="header-anchor" href="#One-transport-window" aria-label="Permalink to &quot;One transport window {#One-transport-window}&quot;">​</a></h2><p>At a high level, each meteorological window follows this sequence:</p><ol><li><p>The driver loads air mass, face mass fluxes, timing, and optional physics fields.</p></li><li><p>The model applies the configured number of transport substeps.</p></li><li><p>Advection follows its symmetric directional palindrome; diffusion and surface fluxes run through StepPlan’s typed midpoint hook; convection and chemistry run at their configured cadence.</p></li><li><p>Requested output times are captured without changing model state.</p></li><li><p>The next forcing window is loaded and checked against the same binary and model contracts.</p></li></ol><p>During cubed-sphere startup, each tracer&#39;s initial dry VMR is converted directly into its slot in the packed model state. This avoids retaining a second complete set of tracer-mass arrays. Signed values and zero initial halos are preserved. The current cubed-sphere runner requires dry-basis transport binaries.</p><p>Across input files, the runner retains the model&#39;s state and numerical workspaces. A new <code>DrivenSimulation</code> refreshes forcing, diffusion layer thickness, and convection caches for the next file. It carries the accumulated simulation clock forward, so time-varying emissions continue at the correct time. GPU prefetch is drained before the runner closes an input driver. When the next file has the same window layout, the new simulation refills the previous one&#39;s window buffers instead of allocating new ones.</p><p>On a GPU, a cubed-sphere transport binary whose on-disk element type is the run&#39;s is loaded window by window with concurrent reads of the payload and unpacking kernels on the device. With discrete device memory (CUDA, ROCm) the reads fill page-locked host memory, uploaded section by section through a section-sized device buffer (<code>MetDrivers.RawWindowStaging</code>). With unified memory (Metal, <code>Architectures.host_memory_model</code>) the reads fill a shared-storage device buffer that the unpack kernels read in place (<code>MetDrivers.MappedWindowStaging</code>): Metal.jl&#39;s host-to-device <code>copyto!</code> synchronizes the queue and stages through a temporary buffer on every call. Either way the device window equals the upload of a window loaded on the host. Other binaries are converted on the host into a page-locked staging window.</p><p>The detailed operator ordering is documented in <a href="/AtmosTransport.jl/previews/PR131/concepts/operators#Operator-concepts">Operators</a>. The mass invariant is derived in <a href="/AtmosTransport.jl/previews/PR131/theory/mass_conservation#Mass-conservation">Mass conservation</a>.</p><h2 id="Where-the-source-lives" tabindex="-1">Where the source lives <a class="header-anchor" href="#Where-the-source-lives" aria-label="Permalink to &quot;Where the source lives {#Where-the-source-lives}&quot;">​</a></h2><p>The source tree mirrors the concepts above:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/</span></span>
<span class="line"><span>├── Grids/           horizontal meshes and hybrid-pressure coordinates</span></span>
<span class="line"><span>├── State/           air mass, conservative tracer storage, forcing fields, and accessors</span></span>
<span class="line"><span>├── Operators/       advection, diffusion, convection, surface flux, chemistry</span></span>
<span class="line"><span>├── MetDrivers/      version-4 binary reader, driver, and window carriers</span></span>
<span class="line"><span>├── Models/          runtime composition; stable Models and child-module paths</span></span>
<span class="line"><span>│   ├── Core/        model, fixed-step simulation, callbacks, step!/run! generics</span></span>
<span class="line"><span>│   ├── Physics/     runtime specs, recipes and metadata</span></span>
<span class="line"><span>│   ├── InitialConditions/  InitialConditionIO: IC and surface-flux loading</span></span>
<span class="line"><span>│   └── Runner/      driven stepping, forcing refresh, adjoint capture and orchestration</span></span>
<span class="line"><span>├── Diagnostics/     core run budgets, snapshot series and mass drift</span></span>
<span class="line"><span>├── SectionTimer.jl  foundation timing and optional NVTX instrumentation</span></span>
<span class="line"><span>├── Preprocessing/   source readers, transforms, balancing, verification, writers</span></span>
<span class="line"><span>├── Output/          snapshot capture and NetCDF/ATMSNAP persistence</span></span>
<span class="line"><span>├── Observations/    observation interfaces, loaded after Output and before Adjoints</span></span>
<span class="line"><span>│   ├── Retrievals/  retrieval columns and averaging kernels</span></span>
<span class="line"><span>│   ├── Sources/     sources, requests, schedules and readers</span></span>
<span class="line"><span>│   └── Sampling/    location, placement, gathers, sampler and observation NetCDF</span></span>
<span class="line"><span>├── Regridding/      conservative offline remapping</span></span>
<span class="line"><span>├── GriddedIO/       conventions of gridded input files (coordinates, time axes, flux units, flux-file schemas)</span></span>
<span class="line"><span>├── Adjoints/        reverse operators and objective seeding</span></span>
<span class="line"><span>├── Tape/            checkpoint schedules and tape storage</span></span>
<span class="line"><span>├── Footprint/       forward-record/reverse-loop footprint workflows</span></span>
<span class="line"><span>├── Inversion/       observations, covariance, cost functions, and optimizers</span></span>
<span class="line"><span>└── Extras/          non-core, no tests, each folder intended as a separate package</span></span>
<span class="line"><span>    ├── Downloads/      DataDownloads: data-source protocols and acquisition</span></span>
<span class="line"><span>    ├── Visualization/  snapshot views and optional Makie integration (ext/ stays)</span></span>
<span class="line"><span>    └── Analysis/       bands, decompositions, skill statistics and reference archives</span></span></code></pre></div><p>The top-level <code>src/AtmosTransport.jl</code> defines the package and curated exports. Most major directories own a module; <code>Footprint/</code> and <code>Inversion/</code> are assembled by <code>Adjoints</code>. Module-level READMEs provide implementation maps for the core runtime directories.</p><p>Modules are included in dependency order, and a module may use only the modules included before it:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Architectures → SectionTimer → ConfigChecks → LogLevels → AtomicFiles</span></span>
<span class="line"><span>→ Quantities → Parameters → Grids → State → Output → Observations → MetDrivers → Operators</span></span>
<span class="line"><span>→ Tape → Adjoints → Regridding → GriddedIO → Preprocessing → Models → Diagnostics</span></span>
<span class="line"><span>→ Extras/Visualization → Extras/Analysis → Extras/Downloads</span></span></code></pre></div><p><code>Diagnostics</code> keeps the run mass-budget checks and their snapshot-reader and global-total helpers in core. <code>Analysis</code> re-exports these names, so diagnostic scripts keep using <code>AtmosTransport.Analysis</code>. Visualization, Analysis post-processing and DataDownloads live under <code>src/Extras/</code>; their module names and plotting exports stay the same. They have no tests and each folder is intended to become its own package. Core must never import Extras; Extras use public core names and helpers declared shared in the owning README. Julia&#39;s optional Makie extension remains in <code>ext/</code>.</p><p>Three single-file modules depend on Base and the standard library only: <code>ConfigChecks.jl</code> checks TOML tables, <code>LogLevels.jl</code> applies the <code>[logging] level</code>, and <code>AtomicFiles.jl</code> publishes a file only when it is complete (a sibling staging file, renamed onto the target on success); the transport-binary writers and the spectral and regridder caches write through it.</p><p><code>GriddedIO</code> is the single owner of the conventions of native gridded input files: coordinate discovery by name, fill policy, lat-lon orientation, source lat-lon meshes, CF time decoding, the surface-flux unit grammar, staging of compressed inputs, and the <code>cs_native</code> and lat-lon flux-file schemas (reader and writer). It sits below both of its consumers, so the runtime initial-condition and surface-flux loaders in <code>Models</code> and the preprocessing code read and write these files through the same functions. See <a href="/AtmosTransport.jl/previews/PR131/api/gridded_io#GriddedIO-API">GriddedIO</a> for the API.</p><h2 id="Contributor-structure-checks" tabindex="-1">Contributor structure checks <a class="header-anchor" href="#Contributor-structure-checks" aria-label="Permalink to &quot;Contributor structure checks {#Contributor-structure-checks}&quot;">​</a></h2><p>The test-only JuliaSyntax checker at <code>scripts/checks/check_structure.jl</code> parses the include tree and extensions without loading the package. The allowed internal module and folder edges live in <code>src/LAYERS.toml</code>, along with a one-directional folder order and reasoned exceptions for existing reverse edges. Core modules cannot depend on Visualization, Analysis, DataDownloads, the Makie extension, or future Extras modules. Existing duplicate helpers, exact body clones, cross-module private uses, and detached docstrings are snapshotted in <code>test/structure/</code>. New violations fail, and allowances only shrink relative to a validated base ref; a missing base fails. Each folder has a 65,000-token size budget (immediate Julia source bytes / 3.5), with exact shrink-only size allowances for today&#39;s oversized folders. README contract headings are reported only in this first rollout.</p><p>The snapshots are keyed by module, folder and file names. A change that moves, renames or splits a unit declares each budget transfer as a reviewed row in <code>test/structure/migrations.toml</code>; the <a href="./../development/structure">structure ratchet page</a> gives the rules. After the merge the rows are inert, and the next edit of that file deletes them.</p><p>Read the <a href="./../development/code_map">generated code map</a> and the folder README before editing. The map lists each folder&#39;s files, size, dependencies, users, public-name count, and forward/adjoint mirrors. The structure gate checks that it matches the source; regenerate it with <code>julia --startup-file=no --project=test scripts/checks/check_structure.jl --write-code-map</code>.</p><p>Run <code>CUDA_VISIBLE_DEVICES= scripts/dev/quick_gate.sh origin/main</code> to check structure alongside required keywords, whitespace, and the selected CPU tests. <code>test/structure/README.md</code> describes the snapshots and static-analysis limits. Numerical behavior is unchanged by these checks.</p><h2 id="Public-workflow-versus-extension-points" tabindex="-1">Public workflow versus extension points <a class="header-anchor" href="#Public-workflow-versus-extension-points" aria-label="Permalink to &quot;Public workflow versus extension points {#Public-workflow-versus-extension-points}&quot;">​</a></h2><p>The stable path for a model user is deliberately small:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>preprocess_transport_binary.jl -&gt; version-4 binaries</span></span>
<span class="line"><span>run_transport.jl               -&gt; configured forward run</span></span>
<span class="line"><span>inspect_transport_binary.jl    -&gt; forcing diagnostics</span></span></code></pre></div><p>The lower-level types are public because research workflows often need custom state initialization, operator experiments, or adjoint objectives. New code should extend the owning abstraction—such as an <code>AbstractConvection</code> method or an <code>AbstractMetReader</code>—instead of adding a parallel runner.</p><h2 id="Continue-through-the-user-guide" tabindex="-1">Continue through the user guide <a class="header-anchor" href="#Continue-through-the-user-guide" aria-label="Permalink to &quot;Continue through the user guide {#Continue-through-the-user-guide}&quot;">​</a></h2><ol><li><p><a href="/AtmosTransport.jl/previews/PR131/concepts/grids#Grids">Grids</a> explains the three horizontal topologies and what the binary infers for you.</p></li><li><p><a href="/AtmosTransport.jl/previews/PR131/concepts/state_and_basis#State-and-basis">State &amp; basis</a> explains why tracers use conservative mass-like storage while users configure and read dry mixing ratios.</p></li><li><p><a href="/AtmosTransport.jl/previews/PR131/concepts/operators#Operator-concepts">Operators</a> describes the selectable physics and their ordering.</p></li><li><p><a href="/AtmosTransport.jl/previews/PR131/concepts/binary_format#Binary-format">Binary format</a> documents the preprocessing/runtime contract in detail.</p></li></ol>`,48))])}const x=i(u,[["render",m]]);export{k as __pageData,x as default};
